function isOpenAITextModel(id){return typeof id==="string"&&/^(?:gpt-(?:4(?:\.1|o)(?:-[A-Za-z0-9._-]+)?|[5-9][A-Za-z0-9._-]*)|o[3-9](?:-[A-Za-z0-9._-]+)?)$/.test(id)&&!/image|audio|realtime|transcribe|tts|search|deep-research/i.test(id)}
