      paras.forEach((t, i) => { if (outgoing || names.some(nm => hasName(t, nm) || hasName(stripMarks(t), nm))) for (let j = Math.max(0, i - 1); j <= Math.min(paras.length - 1, i + 1); j++) keep.add(j); });
      return keep.size ? [`### ${s.heading}\n${paras.filter((_, i) => keep.has(i)).join("\n\n")}`] : [];
