  return { title: p.title || "", summary: p.summary || "", type: p.type || "", cats: (p.categories || []).join(" | "), notices: (p.notices || []).join("\n"),
    infobox: (p.infobox || []).map(r => `${r.label}: ${r.value}`).join("\n"), body, navbox };
