  if (b.pre) sections.push({ heading: "개요", level: 1, body: b.pre });
  let ch = 0;   // "= [2장] 제목 =" 은 장 섹션. 그 아래 하위 섹션도 같은 장이다. [2장]을 지우면 본문 섹션이 된다
