    S.pages[pk] = oldP; S.storyGen = null;
    a.err = err?.code === "cancelled" ? "" : errMsg(err);
    toast(err?.code === "cancelled" ? "장 전환을 취소했습니다. 이전 상태 그대로입니다." : "다음 장을 쓰지 못했습니다. 이전 상태 그대로입니다.");
    if (S.view.name === "advance") renderAll(); else renderSide();
